import heapq

def minCostCompletion(s, a, b):
    heap = []
    cost = 0
    bal = 0
    k = 0
    for ch in s:
        if ch == '(':
            bal += 1
        elif ch == ')':
            bal -= 1
        else:
            cost += b[k]
            heapq.heappush(heap, a[k] - b[k])
            k += 1
            bal -= 1
        if bal < 0:
            if not heap:
                return -1
            cost += heapq.heappop(heap)
            bal += 2
    return cost if bal == 0 else -1
